function validate([m, n, positions]) {
  if (!Number.isInteger(m) || !Number.isInteger(n) || m < 1 || n < 1 || m > 10000 || n > 10000) return 'm and n are between 1 and 10^4.';
  if (m * n > 10000) return 'The map has at most 10^4 cells (m * n <= 10^4).';
  if (!Array.isArray(positions) || positions.length < 1 || positions.length > 10000) return 'positions needs 1 to 10^4 cells.';
  for (const p of positions) {
    if (!Array.isArray(p) || p.length !== 2) return 'Each position is a pair [ri, ci].';
    const [r, c] = p;
    if (!Number.isInteger(r) || !Number.isInteger(c) || r < 0 || r >= m || c < 0 || c >= n) return 'Each position must lie inside the map.';
  }
  return null;
}

