function numIslands2(m, n, positions) {
  const parent = new Array(m * n).fill(-1);
  const size = new Array(m * n).fill(0);
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const answer = [];
  let count = 0;

  const find = (cell) => {
    while (parent[cell] !== cell) {
      parent[cell] = parent[parent[cell]];
      cell = parent[cell];
    }
    return cell;
  };

  for (const [row, col] of positions) {
    const cell = row * n + col;
    if (parent[cell] !== -1) {
      answer.push(count);
      continue;
    }
    parent[cell] = cell;
    size[cell] = 1;
    count++;

    for (const [dr, dc] of directions) {
      const r = row + dr;
      const c = col + dc;
      if (r < 0 || r >= m || c < 0 || c >= n || parent[r * n + c] === -1) {
        continue;
      }
      let rootA = find(cell);
      let rootB = find(r * n + c);
      if (rootA === rootB) {
        continue;
      }
      if (size[rootA] < size[rootB]) {
        [rootA, rootB] = [rootB, rootA];
      }
      parent[rootB] = rootA;
      size[rootA] += size[rootB];
      count--;
    }
    answer.push(count);
  }
  return answer;
}

