function numIslands2(m, n, positions) {
  // Rebuild the map after every addition and count islands with a flood fill.
  const land = Array.from({ length: m }, () => new Array(n).fill(false));
  const result = [];
  for (const [r0, c0] of positions) {
    land[r0][c0] = true;
    const seen = Array.from({ length: m }, () => new Array(n).fill(false));
    let islands = 0;
    for (let r = 0; r < m; r++) {
      for (let c = 0; c < n; c++) {
        if (!land[r][c] || seen[r][c]) continue;
        islands++;
        const stack = [[r, c]];
        seen[r][c] = true;
        while (stack.length) {
          const [x, y] = stack.pop();
          for (const [nx, ny] of [[x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]]) {
            if (nx >= 0 && nx < m && ny >= 0 && ny < n && land[nx][ny] && !seen[nx][ny]) {
              seen[nx][ny] = true;
              stack.push([nx, ny]);
            }
          }
        }
      }
    }
    result.push(islands);
  }
  return result;
}

