function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let m, n, k;
  if (size === 'large') {
    const shape = int(0, 3);
    if (shape === 0) { m = 100; n = 100; }
    else if (shape === 1) { m = 1; n = 10000; }
    else if (shape === 2) { m = 10000; n = 1; }
    else { m = int(20, 100); n = int(20, 100); }
    k = 2000;
  } else {
    m = int(1, 5);
    n = int(1, 5);
    k = int(1, 12);
  }
  // Large lines use a narrow band of cells so additions keep merging long runs.
  const band = size === 'large' && (m === 1 || n === 1) ? int(2000, 4000) : m * n;
  const positions = [];
  for (let i = 0; i < k; i++) {
    const cell = int(0, band - 1);
    positions.push([Math.floor(cell / n), cell % n]);
  }
  return [m, n, positions];
}
